# ─────────────────────────────────────────────────────────────
# src/data.py
# Purpose: builds the two local DuckDB databases the app queries:
#            data/hotels.duckdb  – real hotel booking data (downloaded CSV)
#            data/tpch.duckdb    – TPC-H sample business data (generated by DuckDB)
# Used by:  src/sql_agent.py (DATASETS, db_path), app.py (DATASETS), evals/run_evals.py
# Run directly to (re)build:   python -m src.data
# ─────────────────────────────────────────────────────────────

from pathlib import Path          # handles file paths the same way on Windows/Mac/Linux
import urllib.request             # built-in Python tool to download a file from a URL

import duckdb                     # the local SQL database engine

# Folder of this project = the parent of the "src" folder this file lives in.
PROJECT_DIR = Path(__file__).resolve().parent.parent
# Where the database files and the downloaded CSV are stored (git-ignored via ../../.gitignore "data/").
DATA_DIR = PROJECT_DIR / "data"

# Public hotel booking dataset (Antonio, Almeida & Nunes, 2019), hosted by the TidyTuesday project.
HOTELS_CSV_URL = (
    "https://raw.githubusercontent.com/rfordatascience/tidytuesday/"
    "master/data/2020/2020-02-11/hotels.csv"
)

# The datasets the app offers. Keys are the names shown in the app's dropdown (app.py).
# "file" is the DuckDB database file name inside DATA_DIR.
# "about" is a one-line description given to Claude as context (src/schema.py uses it).
DATASETS = {
    "Hotel bookings": {
        "file": "hotels.duckdb",
        "about": (
            "About 119,000 bookings for two hotels in Portugal (a city hotel and a resort hotel), "
            "with arrivals between July 2015 and August 2017. Each row is one booking, "
            "including cancelled ones."
        ),
    },
    "TPC-H (sample business data)": {
        "file": "tpch.duckdb",
        "about": (
            "The TPC-H benchmark: a wholesale supplier's customers, orders, order line items, "
            "parts, suppliers, nations and regions. Orders are dated 1992-01-01 to 1998-08-02."
        ),
    },
}


def db_path(dataset: str) -> Path:
    """Return the full path of a dataset's database file, e.g. data/hotels.duckdb."""
    return DATA_DIR / DATASETS[dataset]["file"]   # look up the file name in DATASETS above


def build_hotels() -> None:
    """Download the hotel bookings CSV (once) and load it into data/hotels.duckdb."""
    csv_path = DATA_DIR / "hotels.csv"            # where the raw CSV is saved
    if not csv_path.exists():                     # only download if we don't have it yet
        print(f"Downloading {HOTELS_CSV_URL} ...")
        urllib.request.urlretrieve(HOTELS_CSV_URL, csv_path)   # save the file to disk

    con = duckdb.connect(str(db_path("Hotel bookings")))   # open (or create) the database file
    # Build the "bookings" table straight from the CSV.
    #  - nullstr: the CSV writes missing values as "NA" or "NULL"; treat both as real NULLs.
    #  - arrival_date: the CSV splits the date into year / month-name / day; we combine them
    #    into one proper DATE column so questions like "bookings in summer 2016" are easy to write.
    #  - total_nights: weekend + weekday nights, a common thing people ask about.
    con.execute(f"""
        CREATE OR REPLACE TABLE bookings AS
        SELECT
            *,
            -- strptime turns text like '2016 July 5' into a date
            CAST(strptime(arrival_date_year || ' ' || arrival_date_month || ' '
                          || arrival_date_day_of_month, '%Y %B %d') AS DATE) AS arrival_date,
            stays_in_weekend_nights + stays_in_week_nights AS total_nights
        FROM read_csv('{csv_path.as_posix()}', header = true, nullstr = ['NA', 'NULL'])
    """)
    rows = con.execute("SELECT count(*) FROM bookings").fetchone()[0]   # quick sanity check
    con.close()                                   # release the file so the app can open it
    print(f"hotels.duckdb ready: bookings = {rows:,} rows")


def build_tpch(scale_factor: float = 0.1) -> None:
    """Generate the TPC-H tables into data/tpch.duckdb.

    scale_factor 0.1 ≈ 600k line items / 150k orders: big enough to be realistic,
    small enough to build in a few seconds.
    """
    con = duckdb.connect(str(db_path("TPC-H (sample business data)")))   # open/create the file
    con.execute("INSTALL tpch")                   # fetch DuckDB's official TPC-H extension (first time only)
    con.execute("LOAD tpch")                      # switch it on for this connection
    # Only generate if the tables don't exist yet (dbgen fails if they already do).
    exists = con.execute(
        "SELECT count(*) FROM information_schema.tables WHERE table_name = 'lineitem'"
    ).fetchone()[0]
    if not exists:
        con.execute(f"CALL dbgen(sf = {scale_factor})")   # creates customer, orders, lineitem, ...
    rows = con.execute("SELECT count(*) FROM lineitem").fetchone()[0]
    con.close()
    print(f"tpch.duckdb ready: lineitem = {rows:,} rows")


def build_all() -> None:
    """Build every dataset. Safe to run again: it skips work that's already done."""
    DATA_DIR.mkdir(exist_ok=True)                 # create the data/ folder if missing
    build_hotels()
    build_tpch()


# This block only runs when you execute the file directly (python -m src.data),
# not when another file imports it.
if __name__ == "__main__":
    build_all()
